  // Static-first bird images. build_masks.py regenerates DIMS from
  // avian/assets/illustrations/ on every pipeline run, so a DIMS key
  // guarantees the PNG exists and Caddy can serve it directly with no
  // php-fpm worker involved. This matters: a collage render fires one
  // image request per species, and routing those through cutout.php
  // saturated the 5-child fpm pool (pm.max_children warnings). Key
  // order mirrors cutout.php's bundled chain exactly: female pose
  // variant -> female perched -> male pose variant -> male perched.
  // Only species with NO bundled file (assets/cutouts/, rembg cache,
  // Wikipedia fallback) go through cutout.php.
  function birdSlug(sci) {
    return String(sci || '').toLowerCase().replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }
  function birdImg(sci, pose, sex, com, version) {
    var slug = birdSlug(sci);
    var p = +pose > 1 ? '-' + (+pose) : '';
    var keys = [];
    if (sex === 'f') {
      keys.push(slug + '-f' + p);
      if (p) keys.push(slug + '-f');
    }
    keys.push(slug + p);
    if (p) keys.push(slug);
    for (var i = 0; i < keys.length; i++) {
      if (DIMS[keys[i]]) {
        return './avian/assets/illustrations/' + keys[i] + '.png?v=' + version;
      }
    }
    return './avian/api/cutout.php?sci=' + encodeURIComponent(sci) +
      (com ? '&com=' + encodeURIComponent(com) : '') +
      (p ? '&pose=' + (+pose) : '') +
      (sex === 'f' ? '&sex=f' : '') +
      '&v=' + version;
  }
